<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/layout.php';
$user=require_auth();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$status=in_array($_POST['status']??'agendado',['sugerido','agendado','confirmado','concluido','cancelado'],true)?$_POST['status']:'agendado';$q=$pdo->prepare('INSERT INTO agenda (event_date,event_time,client_name,user_id,contact_name,objective,status,source,created_by) VALUES (?,?,?,?,?,?,?,"manual",?)');$q->execute([(string)($_POST['event_date']??date('Y-m-d')),trim((string)($_POST['event_time']??''))?:null,trim((string)($_POST['client_name']??'')),($_POST['user_id']??'')!==''?(int)$_POST['user_id']:null,trim((string)($_POST['contact_name']??'')),trim((string)($_POST['objective']??'')),$status,(int)$user['id']]);$id=(int)$pdo->lastInsertId();audit($pdo,(int)$user['id'],'create','agenda',$id);flash('success','Compromisso adicionado ao cronograma.');}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('cronograma.php');}
$users=$pdo->query("SELECT id,name FROM users WHERE active=1 ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT a.*,u.name user_name FROM agenda a LEFT JOIN users u ON u.id=a.user_id ORDER BY event_date ASC,event_time ASC,id ASC LIMIT 300")->fetchAll();
page_header('Cronograma','cronograma');
?>
<div class="page-actions"><div><span class="eyebrow">AGENDA</span><h2>Cronograma comercial</h2><p>Visitas, retornos e follow-ups programados.</p></div></div>
<div class="card"><form method="post" class="form-grid"><?= csrf_field() ?><label><span>Data</span><input type="date" name="event_date" value="<?= date('Y-m-d') ?>" required></label><label><span>Hora</span><input type="time" name="event_time"></label><label class="span-2"><span>Cliente</span><input name="client_name" required></label><label><span>Responsável</span><select name="user_id"><option value="">—</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?></option><?php endforeach; ?></select></label><label><span>Status</span><select name="status"><option value="agendado">Agendado</option><option value="confirmado">Confirmado</option><option value="sugerido">Sugerido</option></select></label><label class="span-2"><span>Contato</span><input name="contact_name"></label><label class="span-2"><span>Objetivo</span><textarea name="objective" rows="3" required></textarea></label><div class="span-2 form-actions"><button class="btn btn-primary" type="submit">Adicionar ao cronograma</button></div></form></div>
<div class="card"><div class="card-title"><div><span class="tag">AGENDA</span><h3>Próximos registros</h3></div></div><?php if(!$rows): ?><?php empty_state('Cronograma vazio','Nenhum compromisso de demonstração foi incluído.'); ?><?php else: ?><div class="timeline"><?php foreach($rows as $row): ?><article class="timeline-item"><div class="timeline-date"><strong><?= e(date('d/m',strtotime($row['event_date']))) ?></strong><span><?= e($row['event_time']?substr($row['event_time'],0,5):'—') ?></span></div><div><h4><?= e($row['client_name']) ?></h4><p><?= e($row['objective']) ?></p><small><?= e($row['user_name']?:'Sem responsável') ?> · <?= e(ucfirst($row['status'])) ?></small></div></article><?php endforeach; ?></div><?php endif; ?></div>
<?php page_footer(); ?>
